 async function trainingReplay(){
  await ready();if(battling){session.battle.win('p1');snapshotPartner();busy=false;endBattle();}MoveFX.cancel();
  Journey.state.starter='Snivy';Journey.state.party=[Journey.pack(makeMon('Snivy',16,{moves:[33]}),OPENING_DATA.Snivy.growth[16])];NativeStory.state.intro=true;Journey.addItem(50,2);GameSpeed.set(1);
  const captures=[];
  async function candy(cancel){
   let done=false,error,captured=false,pressed=false;const started=performance.now();
   Journey.useRareCandy(0).then(()=>done=true,e=>{done=true;error=e;});
   while(!done){
    check(performance.now()-started<30000,'Evolution timeout');
    const evo=document.getElementById('evolutionScene'),dialog=document.getElementById('dialogue');
    if(evo?.open){
     const progress=Number(evo.dataset.progress||0),canvas=evo.querySelector('canvas');
     if(progress>=32&&!captured){
      const box=canvas.getBoundingClientRect();check(box.width>0&&box.left>=0&&box.right<=innerWidth&&box.top>=0&&box.bottom<=innerHeight,'Evolution canvas clipped');
      const p=pixels(canvas);check(fingerprint(p)!==fingerprint(new Uint8ClampedArray(p.length)),'Empty evolution canvas');
      shot(cancel?'Evoluzione: annullamento con B':'Snivy → Servine: sprite originali',canvas);captures.push({cancel,progress,canvas:[Math.round(box.width),Math.round(box.height)]});captured=true;
      evo.dispatchEvent(new KeyboardEvent('keydown',{key:'a',bubbles:true,cancelable:true}));check(evo.open,'A must not stop evolution');
     }
     if(cancel&&captured&&!pressed){pressed=true;document.querySelector('#touch [data-key="Shift"]').click();}
    }else if(dialog.open){const choices=document.getElementById('starterChoices');if(!choices.hidden)choices.querySelector('button')?.click();else document.getElementById('dialogueContinue').click();}
    await wait(20);
   }
   if(error)throw error;check(captured,'Evolution not rendered');
  }
  try{
   await candy(true);check(Journey.state.party[0].name==='Snivy'&&Journey.state.party[0].level===17,'B cancellation or level-up incorrect');
   await candy(false);check(Journey.state.party[0].name==='Servine'&&Journey.state.party[0].level===18,'Evolution did not complete');
   check(Journey.itemCount(50)===0,'Wrong Rare Candy count');
   await NativeUI.prepare();NativeUI.team();const menu=document.getElementById('nativeMenu');
   await until(()=>menu.getAttribute('aria-label')==='Pokémon','evolved party menu');
   document.getElementById('interact').click();await until(()=>menu.getAttribute('aria-label')==='Azioni Pokémon','evolved party action');
   document.getElementById('interact').click();await until(()=>menu.getAttribute('aria-label')==='Riepilogo di Servine','evolved summary');
   shot('Servine: riepilogo dopo l’evoluzione',menu.querySelector('canvas'));
   await clickMenu('Mosse');await until(()=>[...menu.querySelectorAll('button')].some(b=>b.textContent.includes('Azione')),'evolved move list');
   key(menu,'b');await until(()=>menu.getAttribute('aria-label')==='Pokémon','back from evolved summary');menu.close();
   const dex=NativePokedexDetails.open('Servine',{mode:'zona'});await until(()=>document.getElementById('pokedexEntry')?.open,'evolved habitat');
   const entry=document.getElementById('pokedexEntry');await wait(200);shot('Servine: habitat originale Pokédex',entry.querySelector('canvas'));key(entry,'b');await dex;
   await startBattle(true,{previewLocation:Object.freeze({id:'route1',label:'Percorso 1',terrain:'grass'}),p1:[{name:'Servine',level:18,moves:[536]}],p2:[{name:'Herdier',level:18,moves:[44]}]});busy=true;
   for(const [id,side]of [[536,'p1'],[44,'p2']]){
    await MoveFX.preview(id,side,0,{cryIds:{p1:496,p2:507}});check(MoveFX.active?.profile?.training,'Evolution/opponent custom profile missing');MoveFX.setPreviewFrame(MoveFX.active.profile.impact);drawArena();BattleScreen.cards();shot(side==='p1'?'Servine: Vorticerba':'Herdier avversario: Morso',arena);MoveFX.cancel();
   }
   return {cap:Training.limit(),cancelByTouchB:true,aDoesNotCancel:true,evolved:'Servine',rareCandyCount:0,summary:true,habitat:true,customMovesBothSides:true,captures};
  }finally{if(battling){session.battle.win('p1');snapshotPartner();busy=false;endBattle();}MoveFX.cancel();GameSpeed.set(1);}
 }
